            rla                     ; signs differ: carry = HL negative [274]
            jr $ + 4		; S3d.cls 275
            sbc hl, de		; S3d.cls 276
  ENDM		; S3d.cls 277
; HNEG: HL = -HL (A lost)
  MACRO HNEG		; S3d.cls 279
            xor a		; S3d.cls 280
            sub l		; S3d.cls 281
            ld l, a		; S3d.cls 282
            sbc a, a		; S3d.cls 283
            sub h		; S3d.cls 284
            ld h, a		; S3d.cls 285
  ENDM		; S3d.cls 286
; HABS: HL = |HL| (A lost)
  MACRO HABS		; S3d.cls 288
            bit 7, h		; S3d.cls 289
            jr z, $ + 8		; S3d.cls 290
            HNEG		; S3d.cls 291
  ENDM		; S3d.cls 292
