            add hl, de		; S3d.cls 727
            ld (fn_s3d_render_w_d), hl		; S3d.cls 728
            ld e, (ix + 4)		; S3d.cls 729
            ld d, (ix + 5)		; S3d.cls 730
            ld c, (iy + 4)		; S3d.cls 731
            ld b, (iy + 5)		; S3d.cls 732
