fn_s3d_render_r_tabs:		; S3d.cls 874
            ld iy, arr_s3d_bas            ; {TX}: x - R.x, U.x, F.x (bas + 0, 6, 12) [875]
            ld ix, 36688		; S3d.cls 876
            ld a, 1		; S3d.cls 877
            call fn_s3d_render_tb_three		; S3d.cls 878
