            ld ix, 38224		; S3d.cls 880
            ld a, 1		; S3d.cls 881
            call fn_s3d_render_tb_three		; S3d.cls 882
            ld iy, arr_s3d_bas + 2        ; {TH}: y (heights: 0 - 191) [883]
