            push ix                 ; signed: entries 128-255 (k = -128 .. -1) from -128 v [921]
            ld de, 768		; S3d.cls 922
            add ix, de		; S3d.cls 923
            ld de, (fn_s3d_render_w_v)		; S3d.cls 924
