            or a		; Keys.cls 83
            jr nz, fn_keys_down_kdno		; Keys.cls 84
            ld a, e		; Keys.cls 85
            cp 64		; Keys.cls 86
            jr nc, fn_keys_down_kdno		; Keys.cls 87
            and 7		; Keys.cls 88
            cp 5		; Keys.cls 89
            jr nc, fn_keys_down_kdno		; Keys.cls 90
